UPDATE companies
SET name = #{company.name}, postal_code = #{company.postalCode}, address = #{company.address}, phone = #{company.phone}, email = #{company.email}, license_number = #{company.licenseNumber}, business_hours = #{company.businessHours}, closed_days = #{company.closedDays}, updated_at = UTC_TIMESTAMP(3)
WHERE id = #{company.id}

UPDATE companies
SET status = #{status}, updated_at = UTC_TIMESTAMP(3)
WHERE id = #{companyId}
